def compute(vars):
    total_destinations = vars["v1"]
    continents = 7

    try:
        value = total_destinations / continents
    except ZeroDivisionError:
        return None

    return {
        "value": value,
        "trace": {
            "total_destinations": total_destinations,
            "continents": continents,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "destinations per continent",
            },
        },
    }
